/* @lc app=leetcode id=2183 lang=kotlin */ class Solution { fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b) fun countPairs(nums: IntArray, k: Int): Long = HashMap<Int, Long>().let { cnt -> nums.fold(0L) { acc, x -> gcd(x, k).let { g -> (acc + cnt.entries.filter { (d, _) -> g.toLong() * d % k == 0L }.sumOf { it.value }).also { cnt.merge(g, 1L) { a, b -> a + b } } } } } }